// Helper function to count integers in a sequence
function CountInt(values: seq<obj>) : int
    requires values != null
    ensures CountInt(values) == |{ v | v in values && v is int }|
{
    var count := 0;
    var i := 0;
    while i < |values|
        invariant 0 <= i <= |values|
        invariant count == |{ v | j in 0..i | v in values[j] && v is int }|
    {
        if values[i] is int {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}
